from functools import cmp_to_key


def find_Max_Num(arr, n):
    """Write a python function to find the largest number that can be formed with the given digits."""
    if arr is None:
        return 0

    items = list(arr)
    if n is not None:
        try:
            count = int(n)
        except (TypeError, ValueError):
            count = len(items)
        if count <= 0:
            return 0
        items = items[:count]

    if not items:
        return 0

    parts = [str(item) for item in items]

    def compare(left, right):
        left_first = left + right
        right_first = right + left
        if left_first == right_first:
            return 0
        return -1 if left_first > right_first else 1

    parts.sort(key=cmp_to_key(compare))
    return int("".join(parts))
